def build_index(content_map):
    """把知识内容源预编码成索引：规范词 -> 内容。

    content_map 形如 {"饿": "我饿了。……", ...}（如 human_observer_knowledge.json 的 content）。
    """
    return {k: v for k, v in content_map.items() if k}


def _flatten_clusters():
    """展开翻译表：表达 -> 规范词（长表达优先，避免「肚子饿」被「饿」抢先）。"""
    table = {}
    for term, exprs in SYNONYM_CLUSTERS.items():
        for e in exprs:
            table[e] = term
    # 按长度降序，保证最长表达优先匹配（「肚子咕咕叫」先于「咕咕叫」）
    return dict(sorted(table.items(), key=lambda kv: -len(kv[0])))


PHRASE_TABLE = _flatten_clusters()

# 学科簇 + 人类簇 合并为总翻译表（长表达优先）
DOMAIN_TABLE = dict(sorted(
    ((e, t) for t, exprs in DOMAIN_SYNONYM_CLUSTERS.items() for e in exprs),
    key=lambda kv: -len(kv[0])))
ALL_TABLE = {**PHRASE_TABLE, **DOMAIN_TABLE}


def encode(text, include_domain=True):
    """编码：自然语言 → 语义指纹 {规范词: 权重}。

    权重规则：俗语/多字表达命中 = 1.0（高置信翻译）；
    直接命中规范词本身 = 0.8（原词直译）；
    单字词命中 = 0.6（可能受上下文干扰，需排除表拦截）。
    include_domain=False 时只用人类簇（人话接口专用）。
    """
    if not text:
        return {}
    t = text.lower()
    table = ALL_TABLE if include_domain else PHRASE_TABLE
    fingerprint = {}

    for phrase, term in table.items():
        if phrase.lower() not in t:
            continue
        # 单字词误伤排除
        if len(phrase) == 1:
            excl = SINGLE_CHAR_EXCLUDE.get(phrase, [])
            if any(e in t for e in excl):
                continue
            w = 0.6
        elif phrase == term:
            w = 0.8
        else:
            w = 1.0
        if w > fingerprint.get(term, 0):
            fingerprint[term] = w
    return fingerprint


def decode(fingerprint, index):
    """解码：语义指纹 → 知识条目列表 [(规范词, 权重, 内容)]，按权重降序。"""
    hits = []
    for term, w in fingerprint.items():
        if term in index:
            hits.append((term, w, index[term]))
    hits.sort(key=lambda x: -x[1])
    return hits


def translate(question, index):
    """完整翻译链路：编码 → 解码 → 知识内容。返回 (规范词, 权重, 内容) 或 None。"""
    fp = encode(question)
    if not fp:
        return None
    hits = decode(fp, index)
    return hits[0] if hits else None


def load_human_index():
    """加载「人类观察者」知识源并预编码为索引。"""
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                        'human_observer_knowledge.json')
    with open(path, encoding='utf-8') as f:
        data = json.load(f)
    return build_index(data['content'])


def decode_daily(term):
    """解码到日常：书面语知识词 → 普通人能懂的话（REVERSE_DAILY）。"""
    return REVERSE_DAILY.get(term)


# ============================================================
# 递归检索（v1.16 P1 接口升级）：问题 → 卡定位 → 卡内直接答案
# 「具体问题做一个递归检索」：第一层 graph_retrieve 定位学科卡，
# 第二层在卡 content 条目内匹配直接答案；同时修正 REVERSE_DAILY
# 的规范词选择（多词时取问题中位置最靠后的 = 答案焦点）。
# ============================================================

# 条目拆分：按「数字.」编号切分，引言（编号前）单独一条
_ITEM_SPLIT_RE = re.compile(r"\n\s*\d+\.")
_ITEM_NUM_RE = re.compile(r"\d+\.\s*([^\n]+(?:\n(?!\s*\d+\.)[^\n]+)*)")
# v1.18：支持「①②③」圆圈编号（Python/Rust/TypeScript 卡用 ①动态类型…③GIL…，
# 此前 split_items 只认「1.」不切分 → 整卡当一条 → direct_answer 截 200 字符
# 只到①，③GIL 被砍掉。补圆圈编号切分（②③④⑤⑥⑦⑧⑨⑩）。
_ITEM_CIRCLE_RE = re.compile(
    r"([①②③④⑤⑥⑦⑧⑨⑩])\s*([^\n①-⑩]+(?:\n(?!\s*[①-⑩])[^\n①-⑩]+)*)")


def split_items(content):
    """知识卡 content → 条目列表（引言 + 各编号条目）。

    v1.18：同时支持「1.」数字编号和「①②③」圆圈编号。
    """
    if not content:
        return []
    head = _ITEM_SPLIT_RE.split(content, maxsplit=1)[0].strip()
    # 圆圈编号：切分点找第一个「①」前的部分为引言
    cidx = content.find("①")
    if cidx >= 0:
        head = content[:cidx].strip()
        items = [head] if head else []
        items += [m[1].strip() for m in _ITEM_CIRCLE_RE.findall(content) if m[1].strip()]
        return items
    items = [head] if head else []
    items += [m.strip() for m in _ITEM_NUM_RE.findall(content) if m.strip()]
    return items


def _clean_head(head):
    """裁剪引言噪音：「卡名（知识卡源重建 N 知识点，待重验）——答案…」→ 答案部分。"""
    if "——" in head:
        return head.split("——", 1)[1].strip()
    return head


def _bigram_set(text):
    """二元组集合（去非中文/字母数字字符）。"""
    t = re.sub(r"[^\u4e00-\u9fffA-Za-z0-9]", "", text)
    return {t[i:i + 2] for i in range(len(t) - 1)}


def _pick_daily_term(fp, question):
    """多规范词时选答案焦点词。

    两类问题区分：
      - 定义类（怎么定义/是什么/需要什么条件/什么意思）：焦点是名词短语，
        选最长的规范词（「电流的方向怎么定义」→「电流方向」>「电流」；
        「燃烧需要什么条件」→「燃烧条件」>「燃烧」）
      - 其他（多少度/为什么/哪个）：焦点在句尾，选问题中位置最靠后的
        （「多少度沸腾」→「沸腾」>「大气压」）
    全部不在问题中时按长度最长（更具体）。
    v1.21 修复（2026-08-20 T2 错题）：rfind 找不到的 term（pos=-1，
    规范词组在口语中不连续，如「洗澡用热水舒服」无「热水洗澡」连续串）
    不参与比较——否则被单字「热」抢走焦点 → REVERSE_DAILY 无「热」→ 无直答。
    """
    focus_q = any(w in question for w in
                  ["怎么定义", "是什么", "什么是", "什么意思",
                   "需要什么", "什么条件", "怎么变", "怎么变化"])
    if focus_q and fp:
        # v1.23 修复（知识考古批次2·2026-08-21）：「什么是混沌的边缘」fp 含
        # 「混沌的边缘」(0.8) 和「混沌与蝴蝶效应」(1.0)——原逻辑按
        # (len, weight) 选「混沌与蝴蝶效应」（更长权重更高），但问题焦点是
        # 「混沌的边缘」。优先选问题中实际出现的词（rfind≥0），
        # 再按长度（定义类焦点=名词短语，长词更具体）。
        present = [t for t in fp if t in question]
        if present:
            return max(present, key=lambda t: (len(t), fp.get(t, 0.0)))
        return max(fp, key=lambda t: (len(t), fp.get(t, 0.0)))
    # v1.21 修复（2026-08-20 T2 错题）：
    # 优先「有 REVERSE_DAILY 直答」的词（「热」无直答、「热水洗澡」有——
    # 否则「洗澡用热水舒服」rfind('热水洗澡')=-1 被跳过，单字「热」抢焦点）。
    daily_terms = [t for t in fp if t in REVERSE_DAILY]
    if daily_terms:
        best, best_pos = None, -2
        for term in daily_terms:
            pos = question.rfind(term)
            if pos > best_pos:
                best, best_pos = term, pos
        if best is not None:
            return best
        return max(daily_terms, key=lambda t: (len(t), fp.get(t, 0.0)))
    best, best_pos = None, -2
    for term in fp:
        pos = question.rfind(term)
        if pos < 0:
            continue  # 词未在问题中出现（口语变体）→ 不抢焦点
        if pos > best_pos:
            best, best_pos = term, pos
    if best is not None:
        return best
    # 全部未直接出现 → 取权重最高的长规范词
    return max(fp, key=lambda t: (len(t), fp.get(t, 0.0))) if fp else None


def recursive_item_answer(dex, card_name, fp, question):
    """第二层递归：卡 content 条目匹配直接答案。

    评分：问题二元组与条目交集 ×1.2（实词共现）+ fp 规范词命中 ×0.8。
    门槛：交集 ≥5（≥4 会被「宇宙中心吗」误配到类星体「星系中心」——
    {中心,宇宙,宙中,是宇} 全是通用词撞车；串联 head 交集 ~8 含问题特有词
    「串联/电路/电流」仍可过）。
    返回 (答案文本, 分数) 或 (None, 0)。
    """
    from aeis.core import MemoryLayer as _ML
    from aeis.core import STNode as _STNode
    # v1.16 知识点级精确命中（卡⊃知识点嵌套子图）：
    # 问题规范词直接命中该卡的知识点子节点 → 精确答案（比卡 content 整卡解析更准）
    try:
        card_row = dex.store.conn.execute(
            "SELECT id FROM nodes WHERE layer='knowledge' "
            "AND state_attributes LIKE ? AND tags NOT LIKE '%knowledge_point%' "
            "LIMIT 1", ('%"name": "' + card_name + '%',)).fetchone()
        if card_row:
            card_prefix = card_row[0][:16]
            best_kp, best_s = None, 0.0
            best_name_hit = False  # 名命中（强）：fp 词 in 知识点名 或 名 in 问题
            for r in dex.store.conn.execute(
                    "SELECT state_attributes, content FROM nodes WHERE layer='knowledge' "
                    "AND tags LIKE ? AND tags LIKE ?",
                    ('%knowledge_point%', '%card:' + card_prefix + '%')).fetchall():
                _sa = r[0] or "{}"
                try:
                    import json as _json
                    _pname = _json.loads(_sa).get("name", "")
                except Exception:
                    _pname = ""
                item = (r[1] or "")
                s = 0.0
                name_hit = bool(_pname and _pname in question)
                for term, w in fp.items():
                    if _pname and term in _pname:
                        s += w * 2.0
                        name_hit = True
                    elif term in item:
                        # 内容命中降权（防「重力」in 浮力内容「…所受的重力…」错配）
                        s += w * 0.5
                # 问题关键词窗口匹配（白箱条件感知）：
                # 「气压」→「沸点与气压」名、「高压锅」→ 内容「高压锅内超过100°C」。
                # 名匹配 2-3 字；内容匹配只 3 字（防「重力」2 字泛词误配浮力内容）
                if not name_hit and _pname:
                    _chars = [ch for ch in question if "\u4e00" <= ch <= "\u9fff"]
                    for _L in (4, 3, 2):
                        for _i in range(len(_chars) - _L + 1):
                            _w = "".join(_chars[_i:_i + _L])
                            if _w in _pname:
                                # 窗口越长越精确：4字2.0/3字1.5/2字1.0
                                # （「类型擦除」4字 > 「类型」2字——编译到JS+类型擦除 赢）
                                s += {4: 2.0, 3: 1.5, 2: 1.0}[_L]
                                name_hit = True
                                break
                        if name_hit:
                            break
                    if not name_hit:
                        _content_head = (item or "")[:100]
                        for _i in range(len(_chars) - 2):
                            _w = "".join(_chars[_i:_i + 3])
                            if _w in _content_head:
                                s += 1.5
                                name_hit = True
                                break
                    # 英文词匹配（v1.16：KKT/API/SVM 等缩写不在翻译表）
                    if not name_hit:
                        for _m in re.finditer(r"[A-Za-z]{2,}", question):
                            _ew = _m.group(0).lower()
                            if _ew in (_pname or "").lower() \
                                    or _ew in (item or "")[:100].lower():
                                s += 1.5
                                name_hit = True
                                break
                # bigram 仅加分，不作命中依据（v1.16 修复：
                # 「1加1等于几」↔「棵数等于段数加1」bigram 巧合抢答）
                if s > 0:
                    inter = _bigram_set(question) & _bigram_set(item[:120])
                    if len(inter) >= 2:
                        s += len(inter) * 1.2
                if s > best_s:
                    best_s, best_kp, best_name_hit = s, item, name_hit
            if best_kp:
                if best_name_hit:
                    # 名命中=高置信精确（密度/重力）→ 优先采用
                    return best_kp[:200], max(best_s, 3.6)
                # 纯内容命中（沸腾 in 汽化和液化）→ 低分兜底，
                # 不抢 REVERSE_DAILY 人话答案（「重力」→浮力内容命中错配修复）
                return best_kp[:200], min(max(best_s, 0.5), 3.0)
    except Exception:
        pass
    # v1.16 修复：主库 11045 节点，limit=500 可能不含目标卡 → SQL 精确预过滤
    try:
        _rows = dex.store.conn.execute(
            "SELECT * FROM nodes WHERE layer='knowledge' AND state_attributes LIKE ?",
            ('%"name": "' + card_name + '%',)).fetchall()
        _targets = [_STNode.from_row(tuple(r)) for r in _rows]
    except Exception:
        _targets = []
    for n in _targets:
        sa = n.state_attributes
        if sa.get("name") != card_name:
            continue
        # v1.23 考古卡兜底（知识考古批次1·2026-08-21）：
        # 单概念卡 content 是单段无编号（信息论/动力学/信号处理卡——
        # 「什么是香农熵」「什么是Kuramoto模型」），split_items 只返回
        # 一条 head，bigram 交集 <4 门槛被滤 → direct 空 → 白箱只给导航。
        # 若卡名在问题中且 content 无编号条目（单段），整卡即答案，直接返回。
        _content = n.content or ""
        _items = split_items(_content)
        # v1.23 修复：卡名匹配放宽——问题含卡名 ≥2 字片段即可
        # （「什么是混沌」vs 卡名「混沌与蝴蝶效应」：混沌 in 卡名 ✓；
        #  原判断要求整卡名 in 问题或问题头 in 卡名，都失败）。
        _card_in_q = False
        if card_name:
            if card_name in question:
                _card_in_q = True
            else:
                _cchars = [ch for ch in card_name if "\u4e00" <= ch <= "\u9fff" or ch.isalnum()]
                for _L in (4, 3, 2):
                    for _i in range(len(_cchars) - _L + 1):
                        _seg = "".join(_cchars[_i:_i + _L])
                        if len(_seg) >= 2 and _seg in question:
                            _card_in_q = True
                            break
                    if _card_in_q:
                        break
        if _card_in_q and len(_items) <= 1 and len(_content) > 20:
            # 去掉「卡名：」前缀（考古卡 content 直接以定义开头）
            _direct = _content.strip()
            if _direct.startswith(card_name + "："):
                _direct = _direct[len(card_name) + 1:].strip()
            return _direct[:220], 4.0  # 4.0 ≥ 3.6 门槛 → 作 direct_answer
        qb = _bigram_set(question)
        scored = []
        for raw in split_items(n.content or ""):
            item = _clean_head(raw) if raw.startswith("初中") or "知识卡源" in raw[:30] \
                else raw
            ib = _bigram_set(item)
            inter = qb & ib
            # v1.18：门槛 5→4（Python 卡 GIL 条目与问题「多线程/不并行」交集
            # 因中英混合 bigram 偏少，5 门槛把正确条目滤掉 → 引言当选）。
            # 且引言（卡名行）降权——引言是标题不是答案。
            if len(inter) < 4:
                continue  # 实词交集不足 → 字面噪声，跳过
            s = len(inter) * 1.2
            for term, w in fp.items():
                if term in item:
                    s += 0.8 * w
            # 引言降权：以卡名/「规律性/概述/介绍」开头 = 标题行
            if len(item) < 30 or item.startswith(("Python", "Rust", "TypeScript",
                                                  "规律性", "概述", "介绍")):
                s *= 0.5
            scored.append((s, len(inter), item))
        if scored:
            scored.sort(key=lambda x: (-x[0], -x[1]))
            best_s, _inter, best = scored[0]
            best = re.sub(r"……+$", "", best).strip()  # 去尾部省略号噪音
            # v1.16 修复：110 字符截断砍掉条目尾部的关键知识点
            # （TypeScript 卡「②编译到 JS+类型擦除」的擦除/JS 在 110 之后）。
            # 改智能截断：优先 160 字符内分号边界断，避免关键词被腰斩。
            _cut = 160
            if len(best) > _cut:
                _seg = best[:_cut]
                _cut_at = max(_seg.rfind("；"), _seg.rfind("。"),
                              _seg.rfind("，"), _seg.rfind(";"))
                best = _seg[:_cut_at + 1] if _cut_at > 60 else _seg
            return best, best_s
        return None, 0
    return None, 0


# 问题 → 学科域先验（神经层排名校正 v1.16）
# 快速层空转（fp 空）时，bge 只做字面相似不认学科（「铁球羽毛」→初中地理），
